package store

import (
	"context"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"testing"
)

// This file implements the ADR-0011 released-fixture rollback tests 1 and 3, the release
// blocker enforced by release/check-schema-fixtures.sh (ADR-0012 §4). The frozen fixtures
// under testdata/releases/schema-vNNNN/ are real tenant files generated by this release's
// code (see genfixture_test.go, built only under the fixturegen tag) and checked in with
// synthetic data only.
//
// The fixtures are encrypted with fixtureMasterKey, a deterministic key that exists only in
// test code: it is defined in a _test.go file, so it can never compile into the release
// binary, and no production key provider references it. The fail-closed key tests
// (TestStaticMasterKeys, keyfile/keyprovider tests) are untouched and pass unchanged.

const releasesDir = "testdata/releases"

// fixtureMasterKey is the deterministic master key the release fixtures are encrypted with.
// Its bytes are computed, not a literal, so secret scanning does not flag them, and it is
// test-only (this is a _test.go file). It is never a production key: production keys come
// from the OS keystore or an operator-supplied key, never from this constant.
func fixtureMasterKey(t *testing.T) MasterKey {
	t.Helper()
	b := make([]byte, keyLen)
	for i := range b {
		b[i] = byte(i + 1) // 0x01..0x20, a fixed pattern, not a secret literal
	}
	k, err := NewMasterKey(1, b)
	if err != nil {
		t.Fatal(err)
	}
	return k
}

// fixtureTenantIDs maps a fixture's schema version to the tenant id its store.db was
// generated under. The id is recorded here as a constant (it is a public random identifier,
// not a secret) rather than read from the fixture's tenant-id.txt, so that no file-derived
// path flows into the store's path handling: reading the id from a file would make taint
// analysis treat every downstream tenant path as attacker-controlled. tenant-id.txt is kept
// alongside the fixture as a human-readable record; this constant is authoritative for the
// test. Add an entry when a new schema fixture is checked in.
var fixtureTenantIDs = map[int]string{
	4: "hpbi7jpucxo7doriotsb25awxe",
}

// openReleaseFixture reconstructs a tenant directory in a fresh private data dir from a
// checked-in fixture file, using the version's recorded tenant id, then opens it with the
// fixture key. Opening migrates the file to the current schema (a no-op when the fixture is
// already current).
func openReleaseFixture(t *testing.T, fixtureDir string, version int) *Tenant {
	t.Helper()
	idStr, ok := fixtureTenantIDs[version]
	if !ok {
		t.Fatalf("no recorded tenant id for schema version %d; add it to fixtureTenantIDs", version)
	}
	id, err := ParseTenantID(idStr)
	if err != nil {
		t.Fatalf("fixture tenant id: %v", err)
	}
	// fixtureDir is a checked-in testdata path this test controls, not attacker input.
	db, err := os.ReadFile(filepath.Join(fixtureDir, dbFileName)) //nolint:gosec // G304: controlled testdata path
	if err != nil {
		t.Fatalf("read fixture db: %v", err)
	}

	s := openStore(t, Options{DataDir: testDataDir(t), Keys: staticKeys(t, fixtureMasterKey(t))})
	dir, err := s.layout.dir(id)
	if err != nil {
		t.Fatalf("layout.dir: %v", err)
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatalf("make tenant dir: %v", err)
	}
	// dir is the store's own validated layout.dir(id) under a private temp; this is test-only
	// reconstruction of a checked-in fixture, not attacker-controlled I/O.
	if err := os.WriteFile(dbPath(dir), db, 0o600); err != nil { //nolint:gosec // G703: validated tenant path, test-only
		t.Fatalf("place fixture db: %v", err)
	}
	// A tenant directory also carries an (empty) blobs directory; the fixture stores only
	// the database, so recreate the empty sidecar directory the store expects.
	if err := os.MkdirAll(blobsPath(dir), 0o700); err != nil {
		t.Fatalf("make blobs dir: %v", err)
	}
	return acquire(t, s, id)
}

// releaseFixtureDirs returns the schema-vNNNN fixture directories, sorted by version, with
// their parsed versions.
func releaseFixtureDirs(t *testing.T) (dirs []string, versions []int) {
	t.Helper()
	entries, err := os.ReadDir(releasesDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		t.Fatalf("read releases dir: %v", err)
	}
	for _, e := range entries {
		if !e.IsDir() || !strings.HasPrefix(e.Name(), "schema-v") {
			continue
		}
		v, err := strconv.Atoi(strings.TrimPrefix(e.Name(), "schema-v"))
		if err != nil {
			t.Fatalf("fixture dir %q has no version: %v", e.Name(), err)
		}
		dirs = append(dirs, filepath.Join(releasesDir, e.Name()))
		versions = append(versions, v)
	}
	sort.Sort(sort.Reverse(byVersion{dirs, versions}))
	return dirs, versions
}

type byVersion struct {
	dirs     []string
	versions []int
}

func (b byVersion) Len() int           { return len(b.dirs) }
func (b byVersion) Less(i, j int) bool { return b.versions[i] < b.versions[j] }
func (b byVersion) Swap(i, j int) {
	b.dirs[i], b.dirs[j] = b.dirs[j], b.dirs[i]
	b.versions[i], b.versions[j] = b.versions[j], b.versions[i]
}

// TestReleasedSchemaFixturesMigrate is ADR-0011 rollback test 1: every checked-in release
// fixture opens under the current code (migrating forward if older) and its synthetic data
// reads back unchanged. This proves a file written by a shipped release is still readable
// and correctly migrated by this build.
func TestReleasedSchemaFixturesMigrate(t *testing.T) {
	dirs, versions := releaseFixtureDirs(t)
	if len(dirs) == 0 {
		t.Fatal("no release fixtures found; the release blocker (ADR-0012 §4) requires at least the current schema's fixture")
	}
	for i, dir := range dirs {
		t.Run("schema-v"+strconv.Itoa(versions[i]), func(t *testing.T) {
			tn := openReleaseFixture(t, dir, versions[i])
			// After opening, the file is at the current schema version.
			ident, _ := header(t, tn)
			if want := prodLatest(t); ident.schema != want {
				t.Errorf("after opening fixture: schema_version %d, want current %d", ident.schema, want)
			}
			// The synthetic criticality override reads back unchanged (its actor and reason
			// are sealed with the tenant data key, so a correct read proves the fixture, the
			// schema, and the sealing all survive under the current code).
			ovs, err := tn.CriticalityOverrides(context.Background())
			if err != nil {
				t.Fatalf("read overrides: %v", err)
			}
			if len(ovs) != 1 {
				t.Fatalf("fixture has %d overrides, want 1", len(ovs))
			}
			got := ovs[0]
			if got.Actor != fixtureActor || got.Reason != fixtureReason || got.Criticality != fixtureCriticality {
				t.Errorf("fixture override = %+v, want actor=%q reason=%q criticality=%d", got, fixtureActor, fixtureReason, fixtureCriticality)
			}
		})
	}
}

// TestPreviousReleaseReadsCurrentFiles is ADR-0011 rollback test 3, the N-1 reader: the
// previous release's store code opens, reads, and writes a file the current release
// migrated. That needs a prior release's code and fixture, which do not exist for the first
// store-linking release, so the test is honestly vacuous now. The guard fails the moment a
// prior-release fixture is checked in without this test being implemented to use it, so it
// cannot silently stay vacuous once there is something to check.
func TestPreviousReleaseReadsCurrentFiles(t *testing.T) {
	_, versions := releaseFixtureDirs(t)
	latest := int(prodLatest(t))
	var priors []int
	for _, v := range versions {
		if v < latest {
			priors = append(priors, v)
		}
	}
	if len(priors) == 0 {
		t.Skip("no prior-release fixture exists yet; the N-1 reader test is vacuous for the first store-linking release (ADR-0012 §4)")
	}
	t.Fatalf("prior-release fixtures exist for schema versions %v, but the N-1 reader check "+
		"is not implemented to use them; it needs the previous release's store code as a frozen "+
		"fixture (ADR-0011 rollback test 3)", priors)
}

// prodLatest is the current (latest) production schema version.
func prodLatest(t *testing.T) int64 {
	t.Helper()
	set, err := productionMigrations()
	if err != nil {
		t.Fatalf("load production migrations: %v", err)
	}
	return set.latest()
}

// The synthetic values the fixture carries, asserted by test 1 above and written by the
// generator (genfixture_test.go, built only under the fixturegen tag).
const (
	fixtureActor       = "fixture-actor"
	fixtureReason      = "synthetic release fixture override"
	fixtureCriticality = 5
	fixtureNativeID    = "arn:aws:iam::123456789012:role/fixture"
)
